async function sbRest(path, options = {}) {
  const res = await fetch(SUPABASE_URL + "/rest/v1/" + path, {
    ...options,
    headers: {
      "apikey": SUPABASE_KEY,
      "Authorization": "Bearer " + SUPABASE_KEY,
      "Content-Type": "application/json",
      "Prefer": options.prefer || "return=representation",
      ...(options.headers || {})
    }
  });
  if (!res.ok) {
    const txt = await res.text();
    throw new Error("Supabase error " + res.status + ": " + txt);
  }
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

async function getSnapshot() {
  const [categorias, productos, entidades, movimientos, transacciones, logs] = await Promise.all([
    sbRest("erp_categorias?select=*&order=orden.asc"),
    sbRest("erp_productos?select=*,categoria:erp_categorias(*)&order=codigo.asc"),
    sbRest("erp_entidades?select=*&order=nombre.asc"),
    sbRest("erp_movimientos_stock?select=*,producto:erp_productos(*),entidad:erp_entidades(*)&order=fecha.desc&limit=50"),
    sbRest("erp_transacciones_financieras?select=*,entidad:erp_entidades(*)&order=fecha.desc&limit=50"),
    sbRest("erp_audit_logs?select=*&order=fecha.desc&limit=25")
  ]);
  return {
    categorias: categorias || [],
    productos: productos || [],
    entidades: entidades || [],
    movimientos: movimientos || [],
    transacciones: transacciones || [],
    logs: logs || []
  };
}

async function logAudit(accion, detalle) {
  try {
    await sbRest("erp_audit_logs", {
      method: "POST",
      prefer: "return=minimal",
      body: JSON.stringify({
        usuarioId: DAVID_ID,
        accion,
        detalle,
        fecha: new Date().toISOString()
      })
    });
  } catch (e) {
    // Non-blocking
  }
}

