export default {
  async fetch(request) {
    const url = new URL(request.url);
    const { pathname } = url;

    if (pathname === "/manifest.json") {
      return new Response(JSON.stringify({
        name: "antapharma ERP — Descartables & Esterilización Médica",
        short_name: "antapharma",
        start_url: "/dashboard",
        display: "standalone",
        background_color: "#0F3A40",
        theme_color: "#0F3A40"
      }), { headers: { "Content-Type": "application/json" } });
    }

    if (pathname === "/app.js") {
      return new Response(CLIENT_JS, {
        headers: { "Content-Type": "application/javascript; charset=utf-8" }
      });
    }

    if (pathname === "/api/snapshot") {
      const snap = await getSnapshot();
      return new Response(JSON.stringify(snap), {
        headers: { "Content-Type": "application/json" }
      });
    }

    if (pathname === "/api/action" && request.method === "POST") {
      try {
        const body = await request.json();
        const { action } = body;

        if (action === "login") {
          const email = String(body.email || "").trim().toLowerCase();
          const pass = String(body.password || "").trim();
          if ((email === "antapharma@gmail.com" || email === "david@antapharma.com" || email === "admin@antapharma.com") && 
              (pass === "Antapharma2026!" || pass === "david2026")) {
            await logAudit("INICIO_SESION", "Acceso autorizado a consola privada antapharma ERP — David");
            return new Response(JSON.stringify({ ok: true }), {
              headers: {
                "Content-Type": "application/json",
                "Set-Cookie": "antapharma_session=david_authorized_2026; Path=/; HttpOnly; SameSite=Lax; Max-Age=2592000"
              }
            });
          }
          return new Response(JSON.stringify({ ok: false, error: "Credenciales inválidas. Ingrese con antapharma@gmail.com o david@antapharma.com" }), {
            headers: { "Content-Type": "application/json" }
          });
        }

        if (action === "logout") {
          return new Response(JSON.stringify({ ok: true }), {
            headers: {
              "Content-Type": "application/json",
              "Set-Cookie": "antapharma_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0"
            }
          });
        }

        if (action === "upsert_producto") {
          const payload = {
            codigo: body.codigo,
            nombre: body.nombre,
            categoriaId: body.categoriaId,
            medida: body.medida,
            presentacion: body.presentacion,
            stockActual: Number(body.stockActual),
            stockMinimo: Number(body.stockMinimo),
            precioCosto: Number(body.precioCosto),
            precioVenta: Number(body.precioVenta)
          };
          if (body.id) {
            await sbRest("erp_productos?id=eq." + body.id, {
              method: "PATCH",
              body: JSON.stringify(payload)
            });
            await logAudit("ACTUALIZAR_INSUMO", "Se actualizó insumo " + payload.codigo + " (" + payload.nombre + ")");
          } else {
            await sbRest("erp_productos", {
              method: "POST",
              body: JSON.stringify(payload)
            });
            await logAudit("CREAR_INSUMO", "Alta de nuevo insumo " + payload.codigo + " (" + payload.nombre + ")");
          }
          return new Response(JSON.stringify({ ok: true }), { headers: { "Content-Type": "application/json" } });
        }

        if (action === "delete_producto") {
          await sbRest("erp_productos?id=eq." + body.id, { method: "DELETE" });
          await logAudit("ELIMINAR_INSUMO", "Baja de insumo ID: " + body.id);
          return new Response(JSON.stringify({ ok: true }), { headers: { "Content-Type": "application/json" } });
        }

        if (action === "ajuste_masivo") {
          const catFilter = body.categoriaId === "ALL" ? "" : "&categoriaId=eq." + body.categoriaId;
          const prods = await sbRest("erp_productos?select=id,precioVenta" + catFilter);
          const factor = 1 + (Number(body.porcentaje) / 100);
          for (const p of prods) {
            let nuevo = Math.round(Number(p.precioVenta) * factor);
            nuevo = Math.ceil(nuevo / 10) * 10; // Redondeo múltiplo de 10 (Fórmula Excel)
            await sbRest("erp_productos?id=eq." + p.id, {
              method: "PATCH",
              body: JSON.stringify({ precioVenta: nuevo })
            });
          }
          await logAudit("AJUSTE_PRECIOS", "Ajuste masivo de precios: " + body.porcentaje + "% en " + prods.length + " insumos");
          return new Response(JSON.stringify({ ok: true, actualizados: prods.length }), { headers: { "Content-Type": "application/json" } });
        }

        if (action === "movimiento_stock") {
          const prodArr = await sbRest("erp_productos?id=eq." + body.productoId + "&select=id,stockActual,codigo,nombre");
          if (!prodArr || !prodArr.length) throw new Error("Producto no encontrado");
          const prod = prodArr[0];
          const delta = body.tipo === "ENTRADA" ? Number(body.cantidad) : -Number(body.cantidad);
          const nuevoStock = Math.max(0, Number(prod.stockActual) + delta);

          await sbRest("erp_productos?id=eq." + prod.id, {
            method: "PATCH",
            body: JSON.stringify({ stockActual: nuevoStock })
          });

          await sbRest("erp_movimientos_stock", {
            method: "POST",
            body: JSON.stringify({
              productoId: prod.id,
              tipo: body.tipo,
              cantidad: Number(body.cantidad),
              motivo: body.motivo || "Ajuste operativo",
              entidadId: body.entidadId || null,
              usuarioId: DAVID_ID,
              fecha: new Date().toISOString()
            })
          });

          await logAudit("MOVIMIENTO_STOCK", body.tipo + " de " + body.cantidad + " u. en " + prod.codigo + " (Stock final: " + nuevoStock + ")");
          return new Response(JSON.stringify({ ok: true, nuevoStock }), { headers: { "Content-Type": "application/json" } });
        }

        if (action === "upsert_entidad") {
          const payload = {
            tipo: body.tipo,
            nombre: body.nombre,
            telefono: body.telefono || null,
            email: body.email || null,
            cuit: body.cuit || null,
            direccion: body.direccion || null
          };
          if (body.id) {
            await sbRest("erp_entidades?id=eq." + body.id, { method: "PATCH", body: JSON.stringify(payload) });
            await logAudit("ACTUALIZAR_ENTIDAD", "Ficha comercial actualizada: " + payload.nombre);
          } else {
            await sbRest("erp_entidades", { method: "POST", body: JSON.stringify(payload) });
            await logAudit("CREAR_ENTIDAD", "Nueva entidad agregada: " + payload.nombre + " (" + payload.tipo + ")");
          }
          return new Response(JSON.stringify({ ok: true }), { headers: { "Content-Type": "application/json" } });
        }

        if (action === "delete_entidad") {
          await sbRest("erp_entidades?id=eq." + body.id, { method: "DELETE" });
          return new Response(JSON.stringify({ ok: true }), { headers: { "Content-Type": "application/json" } });
        }

        if (action === "registrar_transaccion") {
          await sbRest("erp_transacciones_financieras", {
            method: "POST",
            body: JSON.stringify({
              tipo: body.tipo,
              monto: Number(body.monto),
              concepto: body.concepto,
              comprobante: body.comprobante || null,
              entidadId: body.entidadId || null,
              fecha: new Date().toISOString()
            })
          });
          await logAudit("FINANZAS_" + body.tipo, body.tipo + " por $" + body.monto + " (" + body.concepto + ")");
          return new Response(JSON.stringify({ ok: true }), { headers: { "Content-Type": "application/json" } });
        }

        if (action === "delete_transaccion") {
          await sbRest("erp_transacciones_financieras?id=eq." + body.id, { method: "DELETE" });
          return new Response(JSON.stringify({ ok: true }), { headers: { "Content-Type": "application/json" } });
        }

        return new Response(JSON.stringify({ ok: false, error: "Acción desconocida" }), { headers: { "Content-Type": "application/json" } });
      } catch (err) {
        return new Response(JSON.stringify({ ok: false, error: err.message }), { headers: { "Content-Type": "application/json" } });
      }
    }

    const authed = isAuthed(request);
    const protectedRoutes = ["/dashboard", "/productos", "/entidades", "/finanzas", "/reportes", "/pami"];
    if (protectedRoutes.includes(pathname) && !authed) {
      return Response.redirect(new URL("/", request.url), 302);
    }
    if (pathname === "/" && authed) {
      return Response.redirect(new URL("/dashboard", request.url), 302);
    }

    return new Response(renderHtml(pathname, authed), {
      headers: { "Content-Type": "text/html; charset=utf-8" }
    });
  }
};
